masks={6:['#..','##.','.#.'],9:['..#','##.','..#'],8:['#.#','.#.','###'],7:['###','.#.','##.'],1:['#..','#.#','.##'],3:['##.','.#.','.##']}
# build 19x13 bg 2; panels at 1,1 and 1,7, etc
out=[[2]*13 for _ in range(19)]
colors=[[6,9],[8,7],[1,3]]
for bi,row in enumerate(colors):
 for bj,col in enumerate(row):
  r=1+6*bi; c=1+6*bj
  for dr in range(5):
   for dc in range(5):
    # border color, interior retains color unless corresponding mask pixel
    if dr in (0,4) or dc in (0,4) or masks[col][dr-1][dc-1]!='#':
     out[r+dr][c+dc]=col
print('\n'.join(' '.join(map(str,r)) for r in out))

